use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Scope;

class TenantScope implements Scope
{
    public function apply(Builder $builder, Model $model): void
    {
        $builder->where('tenant_id', Tenant::current()->id);
    }
}

class Order extends Model
{
    protected static function booted(): void
    {
        static::addGlobalScope(new TenantScope);
    }
}

// Lightweight closure variant — same effect, registered in booted():
class Post extends Model
{
    protected static function booted(): void
    {
        static::addGlobalScope(fn (Builder $b) => $b->where('tenant_id', tenant('id')));
    }
}

// SAFE — every item comes from orders the scope already filtered:
Order::with('items')->get();

// LEAK VECTOR — no Order scope is in play, so no tenant predicate
// is ever added to this query:
OrderItem::where('sku', $sku)->first();

Schema::create('posts', function (Blueprint $table) {
    $table->id();
    $table->unsignedBigInteger('tenant_id');
    $table->string('slug');

    // Correct: uniqueness is per tenant.
    $table->unique(['tenant_id', 'slug']);

    // WRONG: ->unique('slug') — tenant A's 'dashboard' would block
    // every other tenant from ever using that slug, with no error.
});

// The vulnerable shape: scoping that trusts optional context.
class Order extends Model
{
    protected static function booted(): void
    {
        static::addGlobalScope(function (Builder $builder) {
            $tenantId = Tenant::current()?->id;   // null in workers, scheduler, tinker

            if ($tenantId === null) {
                return;                           // contributes NO predicate at all
            }

            $builder->where('tenant_id', $tenantId);
        });
    }
}

// Fail-closed scope: no tenant context => loud exception.
class Order extends Model
{
    protected static function booted(): void
    {
        static::addGlobalScope(function (Builder $builder) {
            $tenantId = Tenant::current()?->id;

            throw_unless($tenantId !== null, new RuntimeException(
                'Tenant-owned query outside tenant context'
            ));

            $builder->where('tenant_id', $tenantId);
        });
    }
}

// The two tests that prove it:
class OrderIsolationTest extends TestCase
{
    public function test_queries_fail_closed_without_tenant(): void
    {
        $this->expectException(RuntimeException::class);
        Order::first();
    }

    public function test_tenant_a_cannot_read_tenant_b(): void
    {
        actingAsTenant($tenantA, function () use ($tenantB) {
            $this->assertNull(Order::where('tenant_id', $tenantB->id)->first());
        });
    }
}

