function filter_by_tenant(array $rows, int $tenantId): array
{
    $result = [];

    foreach ($rows as $row) {
        if (($row['tenant_id'] ?? null) === $tenantId) {
            $result[] = $row;   // null !== 9, so a missing key never leaks in
        }
    }

    return $result;
}

function scoped_where(array $rows, int $tenantId, array $criteria): array
{
    $result = [];

    foreach ($rows as $row) {
        if (($row['tenant_id'] ?? null) !== $tenantId) {
            continue;                       // foreign or missing tenant_id
        }

        $ok = true;
        foreach ($criteria as $k => $v) {
            if (! array_key_exists($k, $row) || $row[$k] !== $v) {
                $ok = false;                // strict: '1' !== 1
                break;
            }
        }

        if ($ok) {
            $result[] = $row;
        }
    }

    return $result;
}

function assert_scoped(array $rows, int $tenantId): array
{
    foreach ($rows as $row) {
        if (($row['tenant_id'] ?? null) !== $tenantId) {
            return [];      // one bad row invalidates everything
        }
    }

    return $rows;           // all scoped: pass through unchanged
}

