// A minimal, safe resolution middleware (sketch):
class ResolveTenantFromHost
{
    public function handle(Request $request, Closure $next)
    {
        $tenant = Tenant::query()
            ->whereHas('domains', fn ($q) => $q->where('domain', $request->getHost()))
            ->firstOrFail();                        // hostname => identity

        app()->instance(TenantContext::class, new TenantContext($tenant));

        return $next($request);
    }
}

// Controllers read the bound context; they never resolve or guess:
$current = app(TenantContext::class)->tenant();

function tenant_db_name(int $tenantId): string
{
    // A DB name may only hold safe characters, so map the int to a
    // deterministic zero-padded string; clamping keeps the output stable.
    $id = max(0, $tenantId);

    return 'tenant_' . str_pad((string) $id, 6, '0', STR_PAD_LEFT);
}

// tenant_db_name(7)      => 'tenant_000007'
// tenant_db_name(12345)  => 'tenant_012345'
// tenant_db_name(0)      => 'tenant_000000'
// tenant_db_name(1234567)=> 'tenant_1234567'  (no truncation)

return [
    // config/queue.php — the database driver stores jobs CENTRALLY, so a
    // worker attached to the central connection can pick up jobs for any
    // tenant and boot that tenant before handling them:
    'database' => [
        'driver'     => 'database',
        'connection' => 'central',     // never a tenant connection
    ],
];

// Manual namespacing (works under any tenancy model):
Cache::put('tenant_' . $tenantId . ':settings', $settings, 600);

// With stancl's CacheTenancyBootstrapper the prefix is added for you
// while tenancy is booted, so plain calls stay isolated:
Cache::put('settings', $settings, 600);        // stored under the tenant prefix

// Feature flags are NOT tenant data — keep them central and un-prefixed:
Cache::put('flags:vat-v2', true, 86400);       // via the central helpers

