// 2) a queue middleware re-resolves and rebinds context before handle():
class RestoreTenantContext
{
    public function handle($job, $next)
    {
        app(TenantContext::class)->set($job->tenantId);
        return $next($job);
    }
}

-- Each tenant-owned table gets a policy that compares the session's
-- tenant setting with the row's tenant_id:
CREATE POLICY tenant_isolation ON orders
    USING (tenant_id = current_setting('app.tenant_id')::bigint);

-- INSERTs need the same predicate as a WITH CHECK policy.
CREATE POLICY tenant_isolation_insert ON orders
    WITH CHECK (tenant_id = current_setting('app.tenant_id')::bigint);

ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

-- The app user usually OWNS the tables (migrations run as it), and the
-- owner bypasses RLS by default — FORCE closes that hole:
ALTER TABLE orders FORCE ROW LEVEL SECURITY;
